body.source:
edition ObjectiveBend 1
import ./Abi.obend as Abi
import ./Text.obend as Text
record State:
  owner: String
  x: Nat
def initial() -> State:
  {owner: "", x: 21n}
def double(state: State) -> Nat:
  state.x + state.x
def render(state: State, context: Abi.Context) -> Nat:
  state.x

